function buildInitials(name?: string) {
  const text = String(name ?? "").trim();
  if (!text) {
    return "";
  }
  const tokens = text.split(/\s+/).filter(Boolean);
  if (tokens.length === 1) {
    return tokens[0].slice(0, 2).toUpperCase();
  }
  return `${tokens[0][0] ?? ""}${tokens[1][0] ?? ""}`.toUpperCase();
